<script setup lang="ts">
import { onMounted, onBeforeUnmount, nextTick, reactive, ref } from 'vue'; import { Chart, registerables } from 'chart.js'; import { Banknote, ShoppingBag, Users, BookOpen } from 'lucide-vue-next'; import { http, errorMessage } from '../../api/http'; import { money, todayVN, dateTime } from '../../utils/format'; import type { Order } from '../../types'; import LoadingState from '../../components/LoadingState.vue'; import StatusBadge from '../../components/StatusBadge.vue'
Chart.register(...registerables); interface Dashboard { totalRevenue: number; totalOrders: number; totalCustomers: number; activeProducts: number; dailyRevenue: { date: string; revenue: number }[]; latestOrders: Order[] }
const data = ref<Dashboard>(), error = ref(''), loading = ref(true), canvas = ref<HTMLCanvasElement>(), filters = reactive({ from: new Date(Date.now() - 29 * 86400000).toISOString().slice(0,10), to: todayVN() }); let chart: Chart | undefined;
async function load() { loading.value = true; error.value = ''; try { data.value = (await http.get<Dashboard>('/admin/dashboard', { params: filters })).data; loading.value = false; await nextTick(); chart?.destroy(); if (canvas.value) chart = new Chart(canvas.value, { type: 'line', data: { labels: data.value.dailyRevenue.map(d => d.date.slice(5)), datasets: [{ label: 'Doanh thu (VND)', data: data.value.dailyRevenue.map(d => d.revenue), borderColor: '#2457D6', backgroundColor: '#EEF3FF', fill: true, tension: .35, pointRadius: 2 }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true, ticks: { callback: v => money(Number(v)) } }, x: { grid: { display: false } } } } }) } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } } onMounted(load); onBeforeUnmount(() => chart?.destroy())
</script>
<template><div class="section-heading"><div><span class="eyebrow">CHÀO MỪNG TRỞ LẠI</span><h1>Tổng quan cửa hàng</h1><p class="muted">Nhìn lại hành trình phát triển của BookNest.</p></div><form class="date-filter" @submit.prevent="load"><label>Từ ngày<input v-model="filters.from" type="date" required></label><label>Đến ngày<input v-model="filters.to" type="date" required></label><button class="btn small">Áp dụng</button></form></div><p v-if="error" class="alert error">{{ error }}</p><LoadingState v-if="loading" /><template v-if="data && !loading"><div class="stat-grid"><article class="stat-card"><span class="stat-icon"><Banknote /></span><small>Doanh thu trong kỳ</small><strong>{{ money(data.totalRevenue) }}</strong><p>Đơn hoàn thành & đã thanh toán</p></article><article class="stat-card"><span class="stat-icon violet"><ShoppingBag /></span><small>Đơn hàng trong kỳ</small><strong>{{ data.totalOrders }}</strong><p>Theo ngày đặt đơn</p></article><article class="stat-card"><span class="stat-icon green"><Users /></span><small>Khách hàng</small><strong>{{ data.totalCustomers }}</strong><p>Toàn hệ thống · Customer</p></article><article class="stat-card"><span class="stat-icon orange"><BookOpen /></span><small>Sách đang bán</small><strong>{{ data.activeProducts }}</strong><p>Toàn hệ thống · Danh mục hoạt động</p></article></div><section class="panel"><h2>Doanh thu theo ngày</h2><p class="muted">Theo ngày hoàn thành · Múi giờ Việt Nam (UTC+7) · Ngày không có doanh thu bằng 0</p><div class="chart-container"><canvas ref="canvas" aria-label="Biểu đồ doanh thu"></canvas></div></section><section class="panel"><div class="section-heading"><h2>Đơn hàng mới nhất</h2><RouterLink to="/admin/orders" class="text-link">Xem tất cả →</RouterLink></div><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày đặt</th><th>Tổng tiền</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="o in data.latestOrders" :key="o.id"><td><RouterLink :to="`/admin/orders/${o.id}`" class="text-link">{{ o.orderCode }}</RouterLink></td><td>{{ o.buyerName }}</td><td>{{ dateTime(o.createdAt) }}</td><td>{{ money(o.totalAmount) }}</td><td><StatusBadge :status="o.orderStatus" /></td></tr><tr v-if="!data.latestOrders.length"><td colspan="5">Chưa có đơn hàng.</td></tr></tbody></table></div></section></template></template>